    diagram: { nodes: [{id:'users',label:'Users',x:10,y:50,detail:'Many concurrent clients create incoming traffic.'},{id:'lb',label:'Load Balancer',x:40,y:50,detail:'Checks health and chooses an available application instance.'},{id:'app1',label:'App 1',x:76,y:20,detail:'A healthy instance serving a share of requests.'},{id:'app2',label:'App 2',x:76,y:50,detail:'A healthy instance serving a share of requests.'},{id:'app3',label:'App 3',x:76,y:80,detail:'Another independently deployable instance.'}], edges:[['users','lb'],['lb','app1'],['lb','app2'],['lb','app3']] }
