function threePartDiagram(left, middle, right, leftDetail, middleDetail, rightDetail) {
  return { nodes: [
    {id: 'left', label: left, x: 12, y: 50, detail: leftDetail},
    {id: 'middle', label: middle, x: 45, y: 50, detail: middleDetail},
    {id: 'right', label: right, x: 78, y: 50, detail: rightDetail}
  ], edges: [['left', 'middle'], ['middle', 'right']] };
}

SYSTEM_TERMS.push(
  {slug:'cdn',number:'07',name:'CDN',category:'Content delivery',short:'A geographically distributed cache that serves static content near the user.',definition:'A Content Delivery Network stores copies of static or cacheable content at edge locations around the world. Users receive files from a nearby location instead of a distant origin server.',why:'Distance adds latency, and one origin can become overloaded by global traffic.',useWhen:['Users are geographically distributed','You serve images, scripts, videos, or download files','Origin capacity and response time need protection'],tradeoffs:['Cached content can be stale','Invalidation takes planning','Dynamic personalised data is less suitable'],example:'A website serves its images and JavaScript from edge locations while its application servers only handle dynamic requests.',diagram:threePartDiagram('User','CDN edge','Origin server','Requests nearby content.','Returns cached content or forwards a miss.','Stores the original files.' )},
  {slug:'dns',number:'08',name:'DNS',category:'Networking',short:'The naming system that translates a domain name into an address a client can reach.',definition:'Domain Name System converts a human-friendly domain such as example.com into the IP address or routing record needed to reach a service.',why:'People and software use stable names, while underlying network addresses and infrastructure can change.',useWhen:['A public or internal service needs a stable name','Traffic must be routed to a provider or region','You need controlled failover or record changes'],tradeoffs:['Changes are delayed by caching and TTLs','Misconfiguration can make a service unreachable','DNS is not a fine-grained health-check system'],example:'A customer visits shop.example.com; DNS points the browser to the current public entry point for that site.',diagram:threePartDiagram('Browser','DNS resolver','Service address','Asks for a domain.','Finds or caches the record.','Receives traffic after resolution.')},
  {slug:'reverse-proxy',number:'09',name:'Reverse Proxy',category:'Networking',short:'A server-side intermediary that receives client traffic before the application.',definition:'A Reverse Proxy sits in front of one or more application servers. It can terminate TLS, route requests, compress responses, cache content, and hide internal infrastructure.',why:'Applications should not each need to solve every edge-networking concern.',useWhen:['You need TLS termination or path-based routing','Several services share one public address','You need a protective layer in front of applications'],tradeoffs:['Adds another hop and component','Incorrect forwarding headers can cause bugs','Needs careful timeout and security configuration'],example:'A proxy accepts HTTPS traffic for several subdomains and routes each path to the right internal service.',diagram:threePartDiagram('Client','Reverse proxy','Application','Sends a public HTTPS request.','Terminates TLS and routes safely.','Processes domain behaviour.')},
  {slug:'rate-limiting',number:'10',name:'Rate Limiting',category:'Protection',short:'A policy that limits how much work a caller can request in a period of time.',definition:'Rate Limiting controls request volume by identity, tenant, IP address, endpoint, or other key. It protects shared capacity and makes usage fairer.',why:'Without limits, a bug, abusive client, or sudden spike can consume capacity needed by everyone else.',useWhen:['An API has shared finite resources','You need fair usage across customers','Expensive endpoints need protection'],tradeoffs:['Legitimate bursts may be rejected','Distributed counters add complexity','A wrong key can unfairly group users'],example:'A public API allows each account 100 write requests per minute and returns a clear retry-after response when the limit is reached.',diagram:threePartDiagram('Caller','Limiter','API service','Requests work.','Allows, delays, or rejects using a quota.','Receives only admitted traffic.')},
  {slug:'idempotency',number:'11',name:'Idempotency',category:'Reliability',short:'The property that repeating an operation produces the same intended result.',definition:'An Idempotent operation can be safely repeated without creating an additional side effect. It is essential when clients, queues, or networks may retry.',why:'Networks fail ambiguously: a caller may not know whether a previous request succeeded before timing out.',useWhen:['Creating payments, orders, or reservations','Consuming at-least-once messages','Clients may retry on timeout'],tradeoffs:['Requires an idempotency key or deduplication state','Key retention has a storage cost','Semantics must be defined per operation'],example:'A checkout client retries a timed-out request with the same idempotency key; the service returns the original order rather than creating another.',diagram:threePartDiagram('Client retry','Idempotency store','Business operation','Sends the same key again.','Finds the prior decision.','Runs once or returns the saved result.')},
  {slug:'retry-backoff',number:'12',name:'Retry & Backoff',category:'Reliability',short:'A controlled way to try transient failures again without making an outage worse.',definition:'Retry repeats an operation that might succeed later. Backoff spaces attempts apart—usually with jitter—so many callers do not retry in lockstep.',why:'Some failures are temporary, but immediate unlimited retries amplify pressure on an already unhealthy dependency.',useWhen:['A dependency has temporary network or capacity failures','The operation is safe to repeat','There is a strict retry budget and timeout'],tradeoffs:['Adds latency before final failure','Unsafe operations can duplicate side effects','Too many retries can cause cascading overload'],example:'A worker retries a temporary HTTP 503 three times using exponential delays with random jitter, then sends the job to a failure queue.',diagram:threePartDiagram('Caller','Backoff policy','Dependency','Receives a transient failure.','Schedules bounded attempts with jitter.','May recover before the budget ends.')},
  {slug:'dead-letter-queue',number:'13',name:'Dead Letter Queue',category:'Asynchronous work',short:'A separate queue for messages that could not be processed successfully.',definition:'A Dead Letter Queue receives messages that exceed their retry limit or cannot be processed safely. It preserves failed work for investigation and deliberate recovery.',why:'Infinite retries block normal work and hide important failures. Dropping failures loses business data.',useWhen:['Background consumers retry messages','Failures need investigation or replay','Poison messages must not block a queue'],tradeoffs:['Requires monitoring and ownership','Replay can repeat side effects','A DLQ is not a substitute for fixing the root cause'],example:'A malformed event fails validation repeatedly, so the consumer moves it to a dead-letter queue with the original payload and error details.',diagram:threePartDiagram('Worker','Retry queue','Dead Letter Queue','Fails to process a message.','Applies bounded retries.','Stores unresolved work for review.')},
  {slug:'database-replication',number:'14',name:'Database Replication',category:'Distributed data',short:'Keeping copies of database data on more than one server.',definition:'Database Replication copies changes from a primary database to one or more replicas. It can improve read capacity, availability, and disaster recovery.',why:'One database server limits read throughput and leaves a single failure domain.',useWhen:['Read traffic exceeds one primary capacity','You need standby or disaster recovery copies','Some reads can tolerate replication lag'],tradeoffs:['Replicas can serve stale data','Failover is operationally complex','Writes usually still concentrate on a primary'],example:'A product catalogue writes to a primary database while read-only browsing requests use nearby replicas.',diagram:threePartDiagram('Primary DB','Replication stream','Read replica','Accepts authoritative writes.','Transfers committed changes.','Serves scalable read traffic.')},
  {slug:'database-sharding',number:'15',name:'Database Sharding',category:'Distributed data',short:'Splitting one logical dataset across multiple independent database partitions.',definition:'Sharding distributes rows across separate database instances using a shard key, such as customer ID or region. Each shard owns only part of the total data.',why:'Eventually, one database machine cannot store or process the full workload economically.',useWhen:['Data or write volume exceeds vertical scaling limits','A stable partition key exists','Cross-shard queries are uncommon or manageable'],tradeoffs:['Cross-shard joins and transactions are harder','Poor shard-key choices create hot shards','Rebalancing data is expensive'],example:'A multi-tenant product assigns each account to a shard based on a stable account identifier.',diagram:threePartDiagram('Router','Shard key','Database shard','Receives a request.','Chooses the owning partition.','Stores one subset of all data.')},
  {slug:'consistent-hashing',number:'16',name:'Consistent Hashing',category:'Distribution',short:'A way to distribute keys so adding or removing nodes moves only a small portion of data.',definition:'Consistent Hashing maps both keys and nodes onto the same logical ring. A key belongs to the next node around the ring, limiting movement when nodes change.',why:'Simple modulo routing can move nearly every key when the number of nodes changes.',useWhen:['Distributing cache keys or partitions','Nodes are frequently added or removed','Stable key placement matters'],tradeoffs:['Virtual nodes are often needed for balance','Debugging placement is less intuitive','It does not solve hot-key problems alone'],example:'A cache cluster adds a new node; only a fraction of keys move to it instead of invalidating the entire cache.',diagram:threePartDiagram('Key','Hash ring','Node','Is converted into a position.','Finds the next assigned node.','Owns that key range.')},
  {slug:'service-discovery',number:'17',name:'Service Discovery',category:'Microservices',short:'A mechanism for finding healthy service instances dynamically.',definition:'Service Discovery lets services locate current healthy instances by name instead of hard-coded addresses. Instances register, deregister, or are discovered through infrastructure.',why:'In dynamic environments, containers and instances come and go; their addresses cannot be safely embedded in application configuration.',useWhen:['Services scale or deploy dynamically','Multiple instances exist behind a service name','Client or platform routing needs health-aware targets'],tradeoffs:['Adds control-plane dependencies','Stale registrations cause failed routing','Caching discovery results needs care'],example:'A payment service asks the discovery system for healthy inventory-service instances before making a request.',diagram:threePartDiagram('Calling service','Discovery registry','Healthy instance','Looks up a service name.','Returns current healthy targets.','Receives the routed request.')},
  {slug:'distributed-lock',number:'18',name:'Distributed Lock',category:'Coordination',short:'A lease that coordinates exclusive work across multiple processes or machines.',definition:'A Distributed Lock gives one participant temporary ownership of a shared operation across a distributed system. It must expire safely and be released by its owner.',why:'Multiple instances can otherwise perform the same scheduled job, migration, or state transition at the same time.',useWhen:['Exactly one worker should run a job at a time','A rare critical section spans multiple instances','A simpler ownership design is not possible'],tradeoffs:['Locks can expire while work is still running','Clock and network failures complicate safety','Overuse reduces availability and throughput'],example:'Only one scheduler instance should generate the daily report; the others skip the run when they cannot obtain the lease.',diagram:threePartDiagram('Worker instance','Lock store','Exclusive job','Requests a time-bound lease.','Grants ownership to one worker.','Runs once while the lease is valid.')},
  {slug:'saga',number:'19',name:'Saga Pattern',category:'Distributed transactions',short:'A sequence of local transactions with compensating actions when a later step fails.',definition:'A Saga coordinates a business workflow across services without using one global database transaction. Each completed step has a compensating action that can undo its business effect if needed.',why:'A distributed transaction across independently owned databases is slow, fragile, or unavailable in most microservice architectures.',useWhen:['A workflow spans multiple service-owned databases','Partial completion must be handled explicitly','Eventual consistency is acceptable'],tradeoffs:['Compensation is not always a perfect undo','Workflow state and observability become complex','Users may temporarily see an intermediate state'],example:'A booking workflow reserves inventory, charges a payment, then confirms delivery. If payment fails, it releases the inventory reservation.',diagram:threePartDiagram('Step succeeds','Next step fails','Compensate','Commits a local action.','Detects workflow failure.','Runs a business undo action.')},
  {slug:'cqrs',number:'20',name:'CQRS',category:'Architecture',short:'Separating models that handle writes from models that serve reads.',definition:'Command Query Responsibility Segregation uses different paths or models for changing state and reading state. The read model can be shaped for fast queries rather than transactional writes.',why:'The best model for enforcing a write is often different from the best model for serving a rich screen or report.',useWhen:['Read and write workloads have different shapes','Complex views need denormalised read models','Eventual consistency in reads is acceptable'],tradeoffs:['Two models increase operational complexity','Read models can be temporarily stale','It is unnecessary for many straightforward applications'],example:'An order service writes normalized order records, while a separate read model builds a ready-to-display order-history view.',diagram:threePartDiagram('Command','Write model','Read model','Changes business state.','Validates and persists truth.','Serves query-optimised views.')},
  {slug:'event-sourcing',number:'21',name:'Event Sourcing',category:'Architecture',short:'Persisting the sequence of state changes instead of only the latest state.',definition:'Event Sourcing records immutable business events such as OrderPlaced and AddressChanged. Current state is rebuilt by replaying events or reading a snapshot plus later events.',why:'The history of how state changed can be as important as the final state itself.',useWhen:['Audit history is a core product need','Business events are meaningful and stable','You need to rebuild alternative views from history'],tradeoffs:['Event schemas must evolve carefully','Debugging and replay require tooling','Not every CRUD domain benefits from it'],example:'An account balance is derived from immutable credit and debit events rather than overwriting one balance field.',diagram:threePartDiagram('Command','Event log','Read state','Causes a business event.','Stores immutable history.','Replays or projects current state.')},
  {slug:'observability',number:'22',name:'Observability',category:'Operations',short:'Understanding a system’s internal behaviour from the signals it emits.',definition:'Observability combines logs, metrics, traces, and meaningful context so engineers can explain what the system is doing and diagnose unexpected behaviour.',why:'Distributed systems fail in ways that cannot be understood from one server or one error message alone.',useWhen:['Services communicate over networks','You need reliable incident response','Performance and business workflows require visibility'],tradeoffs:['Telemetry costs money and adds overhead','Too much unstructured data hides the signal','Sensitive data must be handled carefully'],example:'A trace follows one customer request across gateway, catalogue, and payment services while metrics show which dependency increased latency.',diagram:threePartDiagram('Service','Telemetry platform','Engineer','Emits logs, metrics, and traces.','Correlates system signals.','Investigates behaviour and incidents.')},
  {slug:'horizontal-scaling',number:'23',name:'Horizontal Scaling',category:'Capacity',short:'Adding more service instances instead of making one machine larger.',definition:'Horizontal Scaling increases capacity by running more independent instances behind a traffic distributor. It works best when application instances are stateless.',why:'A single machine has physical limits and remains one failure domain.',useWhen:['Traffic or throughput must grow','You need resilient deployments','Work can be shared across instances'],tradeoffs:['State must move out of process','Coordination problems become distributed','Not all workloads parallelise evenly'],example:'An API grows from two to ten application instances during a peak period while a load balancer distributes requests.',diagram:threePartDiagram('Traffic','Load balancer','Many instances','Arrives from clients.','Distributes requests.','Adds capacity through replicas.')},
  {slug:'cap-theorem',number:'24',name:'CAP Theorem',category:'Distributed data',short:'A way to reason about consistency and availability when a network partition occurs.',definition:'CAP says that when a network partition exists, a distributed data system must choose between always returning a consistent answer and always returning an available answer. Partition tolerance is unavoidable in a networked system.',why:'Network communication can fail or split, so systems must define what they do when replicas cannot agree.',useWhen:['Designing replicated distributed data','Choosing behaviour during regional or network failures','Explaining consistency requirements'],tradeoffs:['Strong consistency can reject or delay requests during a partition','Availability can return stale or conflicting data','The choice is about partition conditions, not a permanent two-of-three menu'],example:'During a link failure between two data replicas, a strongly consistent system may reject writes on one side rather than accept conflicting updates.',diagram:threePartDiagram('Replica A','Network partition','Replica B','Has one copy of the data.','Prevents replicas from communicating.','Has another copy of the data.')}
);

function addFieldNote(slug, name, category, short, definition, why, example, useWhen, tradeoffs) {
  SYSTEM_TERMS.push({
    slug,
    number: String(SYSTEM_TERMS.length + 1).padStart(2, '0'),
    name,
    category,
    short,
    definition,
    why,
    example,
    useWhen,
    tradeoffs
  });
}

[
  ['database-transactions','Database Transactions','Data consistency','A unit of work that either completes together or leaves no partial result.','A Database Transaction groups related reads and writes into one all-or-nothing operation. The database commits every change together or rolls the work back.','Partial writes can leave data contradictory when an operation fails halfway through.','Transferring money updates one balance and the other in one transaction; either both changes commit or neither does.',['Several related writes must remain consistent','A failure must not leave partial state','The data is owned by one transactional database'],['Long transactions hold resources','External calls should not run inside the transaction','Cross-service transactions require another pattern']],
  ['acid-properties','ACID Properties','Data consistency','Four guarantees that make database transactions predictable.','ACID stands for atomicity, consistency, isolation, and durability. Together they describe what a reliable transaction should guarantee.','Teams need a precise language for deciding what a database transaction protects and what it does not.','A completed purchase either stores all required records, avoids exposing intermediate work, and survives a restart.',['You are reasoning about transactional guarantees','You need to choose a database isolation level','You need to explain consistency requirements'],['Stronger isolation can lower concurrency','ACID applies within a transactional system, not automatically across services','Guarantees vary by database and configuration']],
  ['optimistic-locking','Optimistic Locking','Concurrency','A version check that detects a conflicting update instead of blocking first.','Optimistic Locking reads a record with a version and updates it only if that version is still current. A conflicting writer must reload and retry or report a conflict.','Most business records are not edited simultaneously, so blocking every reader would waste capacity.','Two users edit the same profile. The first update increments version 7 to 8; the second update with version 7 is rejected.',['Conflicts are uncommon','A caller can retry or resolve a conflict','You want high read concurrency'],['A user can see a conflict after doing work','Retries need clear behaviour','It is not ideal for hot shared records']],
  ['pessimistic-locking','Pessimistic Locking','Concurrency','A database lock that prevents conflicting writers while work is in progress.','Pessimistic Locking acquires a lock before changing a record so competing transactions wait or fail until the lock is released.','Some high-contention operations cannot safely tolerate optimistic conflicts.','The last available concert seat is locked during checkout so two purchases cannot both confirm it.',['Conflicts are frequent or expensive','The locked work is short','You can set sensible lock timeouts'],['Waiting reduces throughput','Long locks can deadlock','Failures must release locks safely']],
  ['two-phase-commit','Two-Phase Commit','Distributed transactions','A coordinator protocol that asks multiple participants to prepare, then commit together.','Two-Phase Commit coordinates one distributed transaction by collecting prepare votes before telling every participant to commit or abort.','Sometimes multiple transactional systems need one atomic decision, although this is rare in modern service architecture.','A coordinator asks two databases to prepare a transfer, then issues commit only when both report readiness.',['You control all participating systems','Atomicity matters more than availability','Participants support prepare and commit semantics'],['A coordinator failure can block progress','Latency and operational coupling increase','Sagas are often a better service-level alternative']],
  ['leader-election','Leader Election','Coordination','Choosing one active participant to coordinate a shared distributed responsibility.','Leader Election lets a group of nodes agree which one is currently responsible for a task such as scheduling, partition assignment, or metadata changes.','Some work must happen once even though many instances are running.','Several scheduler instances compete for leadership; only the leader starts the hourly cleanup job.',['One active coordinator is required','Leadership can change after failure','A reliable coordination mechanism exists'],['Leadership changes need fencing or leases','Split-brain risks must be controlled','The leader can become a bottleneck']],
  ['quorum','Quorum','Distributed data','A minimum number of replicas that must participate in a read or write decision.','A Quorum uses overlapping groups of replicas so a read can observe a write even when not every replica is available.','Replication needs a deliberate balance between consistency, latency, and availability.','With three replicas, a write quorum of two and read quorum of two ensure the two sets overlap.',['Data is replicated across several nodes','You need tunable consistency','Replica failures are expected'],['Higher quorums increase latency','Replica lag still needs handling','Membership changes are complex']],
  ['data-partitioning','Data Partitioning','Distributed data','Dividing a dataset into smaller logical pieces to improve scale and manageability.','Data Partitioning separates rows by a rule such as range, hash, tenant, or time. It can be implemented within one database or across many shards.','A single large dataset can become slow, expensive, and hard to operate as it grows.','An event table partitions records by month so recent queries touch only current partitions.',['Data has a natural partition key','Queries usually target a subset','Growth requires smaller operational units'],['Cross-partition operations are harder','Bad keys create uneven partitions','Lifecycle and retention rules need design']],
  ['bloom-filter','Bloom Filter','Performance','A tiny probabilistic structure that quickly says a value is definitely absent or possibly present.','A Bloom Filter uses several hash functions and bits to test membership. It never produces false negatives but can produce false positives.','An expensive lookup can often be avoided when the value is definitely not present.','Before checking a huge remote index, a service uses a Bloom Filter to skip keys that cannot exist.',['Most lookups are for missing values','A false positive is acceptable','Memory efficiency matters'],['A positive result still needs verification','False-positive rates grow as the filter fills','Deleted values need special handling']],
  ['websocket','WebSocket','Real-time communication','A persistent two-way connection between a client and server.','WebSocket starts with an HTTP handshake and then maintains a bidirectional channel so both sides can send messages without a new request each time.','Polling adds delay and unnecessary requests when updates need to appear immediately.','A collaborative editor sends live cursor positions and document changes to connected users.',['The server must push frequent updates','Two-way communication is useful','Connection state can be managed at scale'],['Long-lived connections consume resources','Reconnect and ordering logic are required','Load balancing may need connection affinity']],
  ['long-polling','Long Polling','Real-time communication','A request pattern where the server waits before replying until data is available or a timeout occurs.','Long Polling holds a client request open until an update arrives, then the client immediately opens another request.','It offers near-real-time updates where persistent sockets are unavailable or unnecessary.','A notification page holds one request open for up to 30 seconds and receives a response when a new alert arrives.',['Updates are occasional','WebSockets are unavailable or too complex','Clients can reconnect safely'],['Many held connections still cost resources','Repeated reconnects add overhead','It is less efficient than persistent streaming for high volume']],
  ['server-sent-events','Server-Sent Events','Real-time communication','A simple one-way HTTP stream from server to browser.','Server-Sent Events keeps an HTTP response open so the server can push text events to the browser. Browsers automatically reconnect and send a last-event ID.','Many interfaces need live server-to-client updates but do not need clients to send messages on the same channel.','A monitoring page streams live deployment status updates from the server to the browser.',['Updates flow mainly from server to browser','You want simple browser-native reconnection','Text event payloads are sufficient'],['It is one-way','Some intermediaries need streaming configuration','High fan-out still requires careful capacity planning']],
  ['object-storage','Object Storage','Storage','A scalable store for files and blobs addressed by keys rather than database rows.','Object Storage keeps objects such as images, backups, videos, and documents in buckets. Metadata and access policies control how objects are found and retrieved.','Large files do not fit well inside transactional database tables and need cheap, durable storage.','An application stores uploaded photos in object storage and saves only the object key and metadata in its database.',['You store large immutable or semi-immutable files','Durability and low-cost capacity matter','A key-based API is acceptable'],['Listing and renaming semantics differ from a file system','Access controls must be carefully designed','Small-object overhead can matter']],
  ['file-upload-architecture','File Upload Architecture','Storage','A design for receiving large files reliably without overloading the application server.','A File Upload Architecture commonly gives a browser a short-lived signed URL so it uploads directly to object storage, then the application validates and records the result.','Routing large file bytes through application servers wastes bandwidth, memory, and connection capacity.','A user asks for an upload URL, sends a video directly to storage, and the service later processes the stored object.',['Files can be large or numerous','Direct client-to-storage access is possible','Virus scanning or processing is asynchronous'],['Signed URLs need narrow scope and expiry','Partial uploads need cleanup','Validation cannot rely only on client metadata']],
  ['search-engine','Search Engine','Search','A system optimised for finding relevant documents from text queries.','A Search Engine builds an inverted index from terms to documents, allowing fast full-text queries, ranking, filtering, and faceting.','Relational databases are usually not optimised for relevance-ranked search across large text fields.','A store indexes product names and descriptions so users can search by words, filters, and relevance.',['Users need full-text search or ranking','Data can be indexed asynchronously','Search views can be eventually consistent'],['Indexes need updates and monitoring','Ranking quality needs tuning','The search index is another data system to operate']],
  ['etl','ETL Pipeline','Data processing','Extracting data, transforming it, and loading it into a destination for analysis or downstream use.','An ETL Pipeline moves data from source systems, cleans or reshapes it, and writes it into a warehouse, lake, or reporting model.','Operational data is rarely shaped correctly for analytics, reporting, or cross-system insight.','A nightly process copies sales records, standardises currencies, and loads an analytics table for reporting.',['Data comes from several operational sources','Reporting needs a cleaned model','Batch freshness is acceptable'],['Transformations can hide data-quality issues','Backfills need idempotent design','Schema changes need governance']],
  ['stream-processing','Stream Processing','Data processing','Continuously processing events as they arrive rather than waiting for a batch window.','Stream Processing consumes an ordered flow of events and calculates transformations, windows, joins, or aggregates with low latency.','Some decisions and dashboards need fresh results within seconds instead of hours.','A service continuously aggregates click events into a live count of active users per page.',['Events arrive continuously','Low-latency aggregates or reactions matter','Event order and late data can be managed'],['Stateful processing and replays are complex','Late events need policy','Exactly-once claims need careful interpretation']],
  ['batch-processing','Batch Processing','Data processing','Processing a bounded collection of data on a schedule or in a large job.','Batch Processing collects a known set of records and processes them together, usually for reports, backfills, billing, or maintenance.','Some workloads are cheaper and simpler when processed periodically instead of continuously.','A nightly job calculates monthly invoices from all completed usage records.',['Freshness can be measured in minutes or hours','Data is naturally bounded by time','Throughput matters more than immediate response'],['Failures may affect a large batch','Late completion can delay results','Jobs need checkpoints and restartability']],
  ['feature-flags','Feature Flags','Delivery','Runtime switches that control whether a capability is enabled for selected users or environments.','Feature Flags separate deployment from release by allowing a shipped code path to be turned on gradually without another deployment.','Releases need safer rollout and fast rollback than a full code rollback provides.','A new checkout flow is enabled for internal users first, then 5% of traffic, then everyone after metrics look healthy.',['You need gradual exposure','A risky change needs a kill switch','Experiments or tenant-specific behaviour are required'],['Old flags become technical debt','Flag combinations can explode','Sensitive flags need access control and audit']],
  ['blue-green-deployment','Blue-Green Deployment','Delivery','Maintaining two production environments and switching traffic from one to the other.','Blue-Green Deployment runs the old and new application versions side by side. Traffic switches to the new environment only after validation, with the old version ready for quick rollback.','A full deployment needs a low-risk, reversible traffic cutover.','After testing the green environment, a router sends all traffic from blue to green; blue remains available if rollback is needed.',['You can afford duplicate environment capacity','Cutover can be centrally controlled','Database compatibility is planned'],['Double capacity costs more','Stateful migrations remain difficult','A bad shared dependency can affect both environments']],
  ['canary-deployment','Canary Deployment','Delivery','Releasing a new version to a small portion of traffic before wider rollout.','Canary Deployment gradually increases traffic to a new version while metrics and errors are compared with the stable version.','A change may behave differently under real traffic than in tests, so risk should be limited first.','A service sends 1% of requests to the new version, then expands to 10% and 100% when latency and errors stay healthy.',['You can split traffic by version','Metrics are available quickly','Rollback can happen automatically or rapidly'],['Small samples can miss rare problems','Version-specific metrics are required','Data changes must remain compatible']],
  ['zero-downtime-deployment','Zero-Downtime Deployment','Delivery','Releasing software without making the service unavailable to users.','Zero-Downtime Deployment combines multiple instances, health checks, traffic draining, and backward-compatible changes so old and new versions overlap safely.','Users should not experience an outage every time a service changes.','New instances become healthy before old instances stop receiving new requests; existing requests finish before shutdown.',['A service has more than one instance','Changes are backward compatible','Traffic can drain gracefully'],['Database migrations need expand-and-contract discipline','Long requests complicate draining','Not every infrastructure change can be seamless']],
  ['authentication-authorization','Authentication & Authorization','Security','Verifying who someone is and deciding what they are allowed to do.','Authentication establishes identity; Authorization evaluates permissions for a requested action. They are related but must be designed and tested separately.','A valid identity should not automatically gain access to every resource.','A user signs in with a credential, then the service checks whether that user may edit a particular workspace.',['A system has users, services, or roles','Resources have ownership or permission rules','Audit and least privilege matter'],['Permission models grow complex','Caching permissions can create stale access','Identity tokens must be protected']],
  ['oauth-2','OAuth 2.0','Security','A delegated authorization framework that lets an application access a resource without receiving the user password.','OAuth 2.0 issues scoped access tokens after a user or service grants permission through an authorization server.','Applications need limited access to resources owned by users or other services without sharing credentials.','A calendar app asks a user to approve read-only access to their calendar, then uses a scoped token instead of the password.',['Third-party or service-to-service delegation is required','Scopes can express least privilege','A trusted authorization server is available'],['Flows and token lifetimes are easy to misconfigure','Scopes can become too broad','OAuth is authorization; identity needs an appropriate extension such as OpenID Connect']],
  ['jwt','JWT','Security','A signed token format that carries claims between parties.','A JSON Web Token contains encoded claims and a signature so a recipient can verify that an issuer created it and that it was not altered.','Stateless tokens can reduce repeated lookups for short-lived access decisions.','After login, a service issues a short-lived signed token containing the user ID and allowed audience.',['Short-lived portable claims are useful','Recipients can verify signatures','Token revocation requirements are understood'],['Tokens are not encrypted by default','Revocation is harder than server sessions','Large claims increase request size']],
  ['encryption','Encryption in Transit & at Rest','Security','Protecting data while it moves across networks and while it is stored.','Encryption in transit uses protocols such as TLS to protect data between systems. Encryption at rest protects stored data through disk, database, or object-store encryption and managed keys.','Sensitive information can be intercepted in transit or exposed through stolen media and backups.','A service uses HTTPS for every request and encrypted storage with managed keys for uploaded documents.',['Data is sensitive or regulated','Traffic crosses untrusted networks','Backups and storage media need protection'],['Key management is the hard part','Encryption does not replace access control','Performance and recovery procedures need testing']],
  ['web-application-firewall','Web Application Firewall','Security','A protective edge layer that filters malicious or suspicious web requests.','A Web Application Firewall applies rules and threat intelligence to HTTP traffic before it reaches an application.','Common web attacks and abusive patterns should be blocked before consuming application resources.','A WAF blocks known SQL injection patterns and rate-limits suspicious bots before they reach the public API.',['You expose web applications publicly','Common HTTP attack protection is needed','Rules can be monitored and tuned'],['False positives can block valid users','It cannot fix vulnerable application code','Rule maintenance is ongoing']],
  ['multi-tenancy','Multi-Tenancy','Architecture','Serving multiple independent customers from one application while keeping their data and access separate.','Multi-Tenancy shares application infrastructure across tenants while enforcing a clear tenant boundary in every request, query, cache key, event, and audit record.','A shared platform is cheaper to operate than one isolated installation per customer.','A SaaS application stores tenant_id on every business record and verifies the authenticated tenant before each query.',['Many customers use the same product','Shared infrastructure is economically useful','Tenant isolation can be enforced consistently'],['One missing tenant filter can expose data','Noisy tenants need protection','Customisation must not fragment the platform']],
  ['consistency-models','Consistency Models','Distributed data','The rules describing when readers can observe writes across a distributed system.','Consistency Models range from strong consistency, where reads see the latest committed write, to eventual consistency, where replicas converge over time.','Different features need different guarantees; treating every dataset identically wastes either availability or simplicity.','A bank balance may require strong consistency, while a product-view count can converge eventually.',['Data is replicated or asynchronously updated','User expectations differ by feature','You need explicit freshness guarantees'],['Stronger consistency can cost latency and availability','Eventual consistency needs user experience design','The model must be communicated clearly']],
  ['disaster-recovery','Disaster Recovery','Operations','Plans and capabilities for restoring a service after a major outage or data loss event.','Disaster Recovery combines backups, replicated infrastructure, documented procedures, and regular exercises to restore service after a severe failure.','Rare high-impact events cannot be solved during the incident for the first time.','A team restores a database backup into another region during a scheduled recovery exercise and measures the result.',['Business impact of prolonged outage is high','Data loss must be bounded','Recovery procedures can be tested regularly'],['Standby capacity and backup retention cost money','Untested plans often fail','Recovery may still involve data loss']],
  ['rpo-rto','RPO & RTO','Operations','Two targets that define acceptable data loss and acceptable recovery time.','Recovery Point Objective defines how much data loss is acceptable. Recovery Time Objective defines how long a service may be unavailable after a disaster.','Recovery design needs measurable business targets rather than vague expectations of high availability.','An RPO of 15 minutes and RTO of one hour require backups and a recovery process capable of meeting both limits.',['You are planning backups or disaster recovery','Stakeholders need explicit resilience targets','Costs must be matched to business impact'],['Tighter targets cost more','Targets require repeated verification','They do not guarantee zero risk']],
  ['backpressure','Backpressure','Resilience','A way for a slow consumer or dependency to signal that producers must slow down.','Backpressure controls the rate of incoming work when downstream capacity is saturated, using bounded queues, credits, rejection, or flow control.','Unlimited buffering turns a short overload into memory exhaustion and a larger outage.','A streaming consumer accepts only a fixed number of in-flight records; producers pause when that limit is reached.',['Producers can outpace consumers','Queues or buffers have finite capacity','Dropping or delaying work has defined semantics'],['Some work may be delayed or rejected','Capacity limits need tuning','The signal must propagate across boundaries']],
  ['bulkhead-pattern','Bulkhead Pattern','Resilience','Separating resources so one failing dependency cannot exhaust the whole application.','The Bulkhead Pattern allocates independent thread pools, connection pools, queues, or instances to separate workloads and failure domains.','A slow dependency should not consume every shared resource and prevent unrelated healthy work.','An application gives report generation its own small worker pool so it cannot starve checkout requests.',['Workloads have different criticality','One dependency can become slow','Shared resource exhaustion is a risk'],['Unused reserved capacity can be wasteful','Too many pools increase tuning overhead','Dependencies still need timeouts and limits']],
  ['timeouts','Timeouts','Resilience','A maximum wait time after which an operation is treated as failed.','A Timeout bounds how long a caller waits for a response or resource, protecting threads, sockets, and user experience from indefinite waits.','Without time limits, a slow dependency can consume all available resources.','A service gives an external call two seconds, then returns a fallback or controlled error instead of waiting forever.',['A call crosses a network or shared resource','Latency has a business budget','A safe failure path exists'],['Too-short values create false failures','Nested timeouts need a total deadline','Timeouts do not cancel all remote work automatically']],
  ['health-checks','Health Checks','Operations','Signals used by infrastructure to decide whether an instance should receive traffic or be restarted.','Health Checks expose liveness, readiness, and sometimes startup state. Liveness answers whether a process is stuck; readiness answers whether it can serve real traffic safely.','A running process is not necessarily ready to handle requests, especially during startup or dependency failures.','A new application instance reports ready only after its configuration and database connection are validated.',['Instances run behind automation or a load balancer','Deployments require safe admission of traffic','Failures should trigger controlled recovery'],['Overly deep checks can create cascading failure','A passing check can still hide degraded behaviour','Endpoints need protection from abuse']],
  ['graceful-degradation','Graceful Degradation','Resilience','Keeping the most important experience available when a nonessential capability fails.','Graceful Degradation deliberately reduces features or fidelity instead of failing the entire request when a dependency is unavailable.','All-or-nothing behaviour makes a small dependency outage feel like a total product outage.','A storefront still shows products when recommendations are down, but omits the recommendation section and records the fallback.',['Features have different criticality','A useful partial response exists','Fallback behaviour is clear to users'],['Fallbacks can hide persistent incidents','Stale or incomplete responses need clear semantics','Every fallback needs testing and observability']]
].forEach((entry) => addFieldNote(...entry));

const INTERVIEW_QUESTIONS = {
  'api-gateway': [['Easy', 'What problem does an API Gateway solve?'], ['Medium', 'When should a gateway aggregate responses, and when should the client call services directly?'], ['Hard', 'How would you prevent an API Gateway from becoming a single point of failure or a business-logic monolith?'], ['Very hard', 'Design gateway-level rate limiting for millions of users across multiple regions while preserving fair limits per tenant.']],
  'load-balancer': [['Easy', 'Why is a Load Balancer useful when a service has multiple instances?'], ['Medium', 'Compare round-robin, least-connections, and consistent-hash routing.'], ['Hard', 'How would you deploy a new version without dropping in-flight requests?'], ['Very hard', 'How would you route global traffic during a regional outage while avoiding overload in the remaining regions?']],
  cache: [['Easy', 'What is a cache hit and a cache miss?'], ['Medium', 'Explain cache-aside and write-through caching.'], ['Hard', 'How would you invalidate cached user data safely after an update?'], ['Very hard', 'How would you prevent a cache stampede when a popular key expires under heavy load?']],
  'message-queue': [['Easy', 'Why use a queue instead of calling a background service synchronously?'], ['Medium', 'What is the difference between at-most-once and at-least-once delivery?'], ['Hard', 'How would you make a consumer safe when the same message is delivered twice?'], ['Very hard', 'Design an order-event workflow that preserves per-order ordering while scaling consumers horizontally.']],
  'database-index': [['Easy', 'Why can an index make a query faster?'], ['Medium', 'Why might a database ignore an index?'], ['Hard', 'How would you choose column order for a composite index?'], ['Very hard', 'A write-heavy table has a slow query and several indexes. How would you improve the query without making writes unacceptable?']],
  'circuit-breaker': [['Easy', 'What is the purpose of a Circuit Breaker?'], ['Medium', 'Explain closed, open, and half-open states.'], ['Hard', 'How should timeouts, retries, and Circuit Breakers work together?'], ['Very hard', 'How would you tune breaker thresholds for a dependency with naturally bursty latency without hiding a real outage?']]
};

const INTERVIEW_ANSWERS = {
  'api-gateway': [
    'It gives clients one stable entry point while routing requests to internal services and centralising shared concerns such as authentication, rate limits, and API versioning.',
    'Aggregate when the client needs data from several services as one screen-level response. Keep direct calls only when a client genuinely needs a specialised service contract and can safely own that coupling.',
    'Run multiple stateless gateway instances behind a load balancer, keep business rules inside domain services, enforce small gateway responsibilities, and monitor latency, errors, and saturation separately.',
    'Use a distributed rate-limit store or a regional quota allocation model. Key limits by tenant and user, use atomic counters with short windows or token buckets, and choose a bounded fallback when the quota store is unavailable.'
  ],
  'load-balancer': [
    'It routes requests across healthy instances, so capacity grows horizontally and an individual instance failure does not take down the service.',
    'Round-robin is simple and fair for similar requests. Least-connections helps when request duration differs. Consistent hashing keeps a key, such as a user ID, on the same instance when locality or session affinity matters.',
    'Mark new instances healthy before receiving traffic, drain old instances so they stop receiving new requests, allow in-flight work to finish within a deadline, then terminate them.',
    'Use global traffic management with health-aware DNS or anycast, reserve headroom in every region, shift traffic gradually, apply overload protection, and maintain tested failover runbooks.'
  ],
  cache: [
    'A hit means the requested value is already in the cache. A miss means it is absent or expired, so the application must obtain it from the source of truth.',
    'Cache-aside lets the application read the cache first and populate it after a miss. Write-through updates the cache during a write path. Cache-aside is common; write-through can simplify freshness for selected data.',
    'Write to the database first, then invalidate or update the exact cache key. Use tenant-safe keys, versioned values when needed, and accept that concurrent readers may see a short stale window.',
    'Use request coalescing so one request refreshes the value while others wait or receive stale-but-safe data. Add jitter to expirations, apply stale-while-revalidate, and protect the database with limits.'
  ],
  'message-queue': [
    'A queue removes background work from the request path. The producer can respond quickly, while consumers process reliably at their own speed and retry failures.',
    'At-most-once can lose a message but does not repeat it. At-least-once retries until acknowledgement, so a consumer can receive a duplicate and must be idempotent.',
    'Use an idempotency key or a processed-message record with a unique constraint. Make the business write and deduplication decision atomic where possible.',
    'Partition messages by order ID so all events for one order go to one ordered partition. Scale with many partitions, keep consumers idempotent, and model retries and dead-letter handling explicitly.'
  ],
  'database-index': [
    'An index stores ordered lookup information, allowing the database to seek to matching rows instead of examining every row in a table.',
    'The optimiser may prefer a table scan when a query returns a large percentage of rows, statistics are inaccurate, the predicate transforms the indexed column, or the index order does not match the query.',
    'Put equality-filter columns first, then range or sort columns, based on real query patterns. Validate the choice with an execution plan rather than guessing.',
    'Measure the exact slow query and write cost, remove redundant indexes, add the smallest useful composite or partial index, and re-check latency plus insert/update throughput under production-like load.'
  ],
  'circuit-breaker': [
    'It stops repeatedly calling an unhealthy dependency. That fails fast, preserves local resources, and prevents a dependency outage from becoming a wider outage.',
    'Closed sends normal calls and records outcomes. Open rejects calls immediately after the failure threshold. Half-open allows a small number of test calls; success closes it, failure opens it again.',
    'Set a realistic timeout first. Retry only transient failures with a small bounded budget and backoff. Place the breaker around the remote dependency so persistent failures fail fast instead of multiplying work.',
    'Base thresholds on latency and error baselines, use separate timeout and error signals, require a meaningful sample size, limit half-open probes, and review false opens versus delayed incident detection through metrics.'
  ]
};

SYSTEM_TERMS.forEach((term) => {
  if (INTERVIEW_QUESTIONS[term.slug]) return;
  INTERVIEW_QUESTIONS[term.slug] = [
    ['Easy', `What is ${term.name}, in simple terms?`],
    ['Medium', `What problem does ${term.name} solve, and when would you use it?`],
    ['Hard', `What are the main trade-offs or failure modes of ${term.name}?`],
    ['Very hard', `How would you introduce ${term.name} into a high-traffic production system and prove it is helping?`]
  ];
  INTERVIEW_ANSWERS[term.slug] = [
    term.definition,
    `${term.why} Use it when the conditions fit: ${term.useWhen[0].toLowerCase()}.`,
    `Key trade-offs include ${term.tradeoffs.slice(0, 2).join(' and ').toLowerCase()}. The design should make those costs visible through testing and monitoring.`,
    `Start with a clear success metric, introduce it behind a controlled rollout, instrument latency, errors, and capacity, test failure paths, and compare measured results against the simpler baseline.`
  ];
});
